import { Order, Product } from "@/types";
import { SetStateAction } from "react";
import jsPDF from 'jspdf'

const API_BASE = (process.env.NEXT_PUBLIC_BACKEND_API_URL ?? 'http://localhost:4001').replace(/\/$/, '')


export function getSellerOrders(
    token: string,
    setOrders: React.Dispatch<SetStateAction<Order[]>>,
    setLoading: React.Dispatch<SetStateAction<boolean>>) {
    setLoading(true);
    fetch(`${API_BASE}/api/orders/seller-orders`, {
        headers: { Authorization: `Bearer ${token}` },
    })
        .then(res => {
            if (!res.ok) throw new Error("Failed to fetch orders")
            return res.json()
        })
        .then((data: { orders: Order[] }) => setOrders(data.orders || []))
        .catch(err => console.error(err))
        .finally(() => setLoading(false))
}

