export type SellerStats = {
    totalOrders: number
    pendingOrders: number
    earnings: number
    products: number
}

export function getSellerStats(
    token: string,
    setStats: React.Dispatch<SetStateAction<SellerStats>>,
    setLoading?: React.Dispatch<SetStateAction<boolean>>,
) {
    setLoading?.(true)
    fetch(`${API_BASE}/api/orders/seller-stats`, {
        headers: { Authorization: `Bearer ${token}` },
    })
        .then(res => {
            if (!res.ok) throw new Error('Failed to fetch stats')
            return res.json()
        })
        .then((data: SellerStats) => setStats({
            totalOrders: Number(data.totalOrders ?? 0),
            pendingOrders: Number(data.pendingOrders ?? 0),
            earnings: Number(data.earnings ?? 0),
            products: Number(data.products ?? 0),
        }))
        .catch(err => console.error(err))
        .finally(() => setLoading?.(false))
}


export function handlePrintReceipt (order: Order) {

    const doc = new jsPDF;


    const logoBase64 = 'data:image/png;base64,';

    // Add logo or text branding
    doc.addImage(logoBase64, 'PNG', 85, 15, 45, 20);

    // Order information

    // Bold font
    doc.setFontSize(18);                  // Bigger size
    doc.setFont('montserrat', 'bold');
    doc.text(`Order Receipt`, 105, 45, { align: 'center' })
    doc.setFontSize(12)
    doc.setFont('montserrat', 'normal'); // Normal font
    doc.text(`Order ID: ${order._id}`, 15, 60)
    doc.text(`Date: ${new Date(order.createdAt).toLocaleDateString()}`, 15, 67)
    doc.text(`Customer: ${order.customer?.firstName + ' ' + order.customer?.lastName}`, 15, 74)
    doc.text(`Email: ${order.customer?.email}`, 15, 81)
    //TODO: add contact in schema
    doc.text(`Contact: ${order.customer?.phoneNumber || 'N/A'}`, 15, 88)
    doc.text(`Shipping Address: ${order.shippingAddress.street + ', ' + order.shippingAddress.city + ', ' + order.shippingAddress.state + ', ' + order.shippingAddress.zipCode}`, 15, 95)

    // Table header
    doc.setFont('montserrat', 'bold');
    let startY = 105
    doc.text('Items Ordered:', 15, startY)
    startY += 10

    doc.text('Product ID', 15, startY)
    doc.text('Product Name', 50, startY)
    doc.text('Qty', 110, startY)
    doc.text('Price', 130, startY)
    doc.text('Subtotal', 160, startY)

    startY += 4
    doc.line(15, startY, 195, startY)

    // Items ordered details
    doc.setFont('montserrat', 'normal'); // Normal font
    startY += 8
    order.items.forEach((item) => {
      const productId = typeof item.product === 'string' ? item.product : item.product._id
      const productName = typeof item.product === 'string' ? 'N/A' : item.product.name || 'N/A'
      
      doc.text(`${productId}`, 15, startY, { maxWidth: 30 })
      doc.text(`${productName}`, 50, startY, { maxWidth: 55 })
      doc.text(`${item.quantity}`, 110, startY)
      doc.text(`${(item.salePrice ?? item.price).toLocaleString()}`, 130, startY)
      doc.text(`${((item.salePrice ?? item.price) * item.quantity).toLocaleString()}`, 160, startY)
      startY += 7
    })
    doc.setFont('montserrat', 'bold');
    // Total amount
    startY += 5
    doc.line(15, startY, 195, startY)
    startY += 8
    doc.text(`Total Amount: ${order.totalAmount.toLocaleString()}`, 15, startY)

    // Save PDF file
    // Open PDF preview in a new browser tab
    const blob = doc.output('blob');
    const url = URL.createObjectURL(blob);
    window.open(url);
  }

  